+function stripTablePresentationStyles(root: HTMLElement) {
+  root
+    .querySelectorAll("table, colgroup, col, tbody, thead, tr, td, th")
+    .forEach((el) => {
+      const htmlEl = el as HTMLElement;
+
+      const style = htmlEl.getAttribute("style");
+      if (style) {
+        const safeStyles = style
+          .split(";")
+          .map((s) => s.trim())
+          .filter((s) => {
+            const prop = s.split(":")[0]?.trim().toLowerCase();
+            return ["background", "background-color", "color", "font-weight"].includes(prop);
+          })
+          .join("; ");
+
+        if (safeStyles) {
+          htmlEl.setAttribute("style", safeStyles);
+        } else {
+          htmlEl.removeAttribute("style");
+        }
+      }
+
+      htmlEl.removeAttribute("class");
+    });
+}
+
 // Post-process Tiptap JSON to inject textStyle marks (color, fontSize, backgroundColor)
